tape( 'the constructor has a read-only `name` property', function test( t ) {
	t.strictEqual( Value.name, 'Value', 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON', function test( t ) {
	var expected;
	var json;
	var v;

	v = new Value();
	json = v.toJSON();

	expected = {};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON (options)', function test( t ) {
	var expected;
	var json;
	var v;

	v = new Value({
		'band': 0.5,
		'color': {
			'r': {
				'value': 255
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 0
			}
		},
		'exponent': 2,
		'field': 'price',
		'mult': 2,
		'offset': 5,
		'round': true,
		'scale': 'xScale',
		'signal': 'width',
		'value': 5
	});
	json = v.toJSON();

	expected = {
		'band': 0.5,
		'color': {
			'r': {
				'value': 255
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 0
			}
		},
		'exponent': 2,
		'field': 'price',
		'mult': 2,
		'offset': 5,
		'round': true,
		'scale': 'xScale',
		'signal': 'width',
		'value': 5
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the `toJSON` method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var expected;
	var v;

	v = new Value({
		'field': 'price'
	});

	expected = {
		'field': 'price'
	};
	t.strictEqual( JSON.stringify( v ), JSON.stringify( expected ), 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which is an EventEmitter', function test( t ) {
	var v = new Value();
	t.strictEqual( instanceOf( v, EventEmitter ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor ignores unrecognized options', function test( t ) {
	var v = new Value({
		'field': 'price',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( v.field, 'price', 'returns expected value' );
	t.strictEqual( v.beep, void 0, 'returns expected value' );
	t.strictEqual( v.foo, void 0, 'returns expected value' );

	t.end();
});
